    note.append(page('7. Плательщики, сроки и ликвидность',*payblocks,
        h('Условия до обязательств'),p('C0 подтверждается в R1-R2 на полный запуск и выплачивается по этапам приёмки до эксплуатации. '
          'Anchor платится за принятый якорный объём, commercial - за принятые заказы. Оператор согласует расходы OPEX с поступлениями. '
          'Отдельный ENV-gap подтверждается сверх anchor до эксплуатации. AGRI нужны права на поля и сезон, ENV - лаборатория и публикация, '
          'FLOOD - обследования и полномочия штаба, TRANS - телематика и фактические прибытия. Заключённые договоры не заявлены.'),
        p('Финансовый руководитель каждого оператора совместно с ведущим плательщиком C0 согласует календарь, авансы и оборотный капитал. '
          'Без кассового обеспечения запуск запрещён. Годовые суммы не делятся на месяцы как доказательство ликвидности. Платёжные дни, сезонность и стоимость миграции неизвестны. A07-A10.',size=9.8)))
    contractblocks=[]
    for card in services:
        contractblocks += [h(card['lot_id']+' '+card['mode_id']),
          p(cooperation[card['lot_id']],size=9.5)]
    note.append(page('8. Доступ, закупка и ответственность',
        p('A: ENV/FLOOD — бесплатные недискриминационные сводки, платные индивидуальные расширения; C: AGRI/TRANS — договорные клиенты и ограниченный anchor. '
          'Чувствительные поля/пробы/телематика по правам. B не выбран. A/B/C не юридические или научные конструкции.'),*contractblocks,
        p('Перед выбором закупщик проверяет зрелость результата, реальный спрос, пригодных поставщиков и критичность: эти местные условия неизвестны, readiness не TRL. '
          'Права/финансирование и контрольный набор — до обязательств; оплачивается принятый объём. Одна схема и общая НИОКР не обязательны. O1, PDF с.7–11.',size=9.5),
        p('Реальные агрономы, пользователи сводки, полевые группы и диспетчеры возвращают ошибки/пропуски; поставщик отвечает исправлением либо мотивированным ограничением; '
          'указанный отраслевой приёмщик утверждает версию и переход по местному контрольному набору. Пользователь отвечает за отраслевое решение, оператор — за сервис. O2, PDF с.10–11. Полные условия доступа/приёмки: protocols.md.',size=9.5)))
    note.append(page('9. STRESS и управленческий ответ',p(stress,size=12),
        bars(['Стоимость','BASE лимит','STRESS лимит'],[f['c0_mrub'],s['base']['c0_limit'],s['stress']['c0_limit']],
          'C0 и лимиты, млн руб. Уменьшение бюджетного потолка не изменяет стоимость лотов.'),
        table(['Показатель','BASE','STRESS'],[[label,n(f[key]),n(f[key])] for label,key in [('OPEX','opex_mrub_per_year'),('CASH','cash_mrub_per_year'),('VPUB','vpub_mrub_per_year'),('KCASH','kcash'),('Адресные gaps','sum_lot_funding_gaps')]],size=9.6),
        h('Сохранить при выполнении условий'),*[p(x,size=10) for x in s['conditions']],
        p('Ответственный: '+s['owner']+'.'),p(s['timing']),
        p('Состав, режимы, общественный доступ и полные денежные потоки сохраняются. Запас C0 не выделенные деньги и не OPEX-резерв. '
          'При отказе плательщика нужен новый расчёт и повторное решение, а не автоматическая экономия по исходным лотам. S1/S5, A08-A10.',size=9.6)))
    riskrows=[]
    for card in services:
        riskrows.append([card['lot_id'], '; '.join(r['risk'] for r in card['risks']),card['risks'][0]['owner']])
    switch=c['supplier_switch']
